double meanAbsoluteDeviation(List<double> numbers) {
  final double sum = numbers.fold(0.0, (a,b)=>a+b);
  final double average = sum / numbers.length;

  return numbers.fold(0.0, (prev,current) => prev + ((current - average).abs()));
}

