double meanAbsoluteDeviation(List<double> numbers) {
  final sum = numbers.reduce((a, b) => a + b);
  return numbers.map(
        (number) => (sum / numbers.length - number).abs(),
      ).reduce((value1, value2) => value1 + value2) / numbers.length;
}

