def count_distinct_characters(string_arg0: str) -> int:
    """Given a string, find out how many distinct characters (regardless of case) does it consist of
    >>> count_distinct_characters("xyzXYZ")
    3
    >>> count_distinct_characters("Jerry")
    4
    """


def count_distinct_characters(string: str) -> int:
    return len(set(string.lower()))

dart_source:
int countDistinctCharacters(String string) {
  if (string.length == 0) return 0;

  int distinct = 1;

  for (int i = 1; i < string.length; i++) {
    String currentCharacter = string[i];

    bool foundMatch = false;
    for (int j = 0; !foundMatch && j <= i - 1; j++) {
      if (currentCharacter.toLowerCase() == string[j].toLowerCase()) {
        foundMatch = true;
      } 
    } 

    if (!foundMatch) {
      distinct++;
    }
  } 

  return distinct;
}

