  final candidate = countDistinctCharacters;

  expect(candidate(""), 0);
  expect(candidate("abcde"), 5);
  expect(candidate("abcdecadeCADE"), 5);
  expect(candidate("aaaaAAAAaaaa"), 1);
  expect(candidate("Jerry jERRY JeRRRY"), 5);
}

