    "q",
    "r",
    "s",
    "t",
    "u",
    "v",
    "w",
    "x",
    "y",
    "z"
  ];

  String result = "";

  for (int i = 0; i < s.length; i++) {
    int index = alphabet.indexOf(s[i]);
    if (index != -1) {
      result += alphabet[(index + 4) % alphabet.length];
    } else {
      result += s[i];
    }
  }

  return result;
}

