dart_source:
List<String> wordsString(String s) {
  final List<String> output = [];

  if (s.isEmpty) return output;

  int i = 0, n = s.length;

  while (i < n) {
    String word = '';

    // Skip leading whitespace and commas.
    while (i < n && (s[i] == ' ' || s[i] == ',')) {
      ++i;
    }

    // If we have reached the end of string without a valid character 
    // it means there was trailing comma or whitespace at the end, so exit.
    if (i >= n) break;

    // Now read characters until next comma or space is encountered, building up word.
    while (i < n && s[i] != ',' && s[i] != ' ') {
      word += s[i];
      ++i;
    }

    // Add to output list only if non-empty word formed
    if (word.isNotEmpty) {
      output.add(word);
    }

    // Skip over any comma that might be following this token before moving on to next one.
    if (i < n && s[i] == ',') {
      ++i;
    }
  }

  return output;
}

