List<int> maximum(List<int> arr, int k) {
  List<int> result = [];

  // Sort the array in ascending order.
  arr.sort();

  // Add elements to the list starting from the end of the sorted array.
  for (int i = arr.length - 1; i >= 0 && result.length < k; i--) {
    result.add(arr[i]);
  }

  return result.reversed.toList();
}

