  // Sort them
  thirdElements.sort();

  // Put them back
  int thirdIndex = 0;
  for (int i = 0; i < result.length; i += 3) {
    result[i] = thirdElements[thirdIndex];
    thirdIndex++;
  }

  return result;
}

