@pragma('vm:entry-point')
String encode(String message) {
  const vowels = "aeiouAEIOU";
  final vowelsReplace = <String, String>{};

  for (int i = 0; i < vowels.length; i++) {
    vowelsReplace[vowels[i]] = String.fromCharCode(vowels.codeUnitAt(i) + 2);
  }

  final swappedMessage = _swapCase(message);

  final result = StringBuffer();
  for (int i = 0; i < swappedMessage.length; i++) {
    final char = swappedMessage[i];
    if (vowelsReplace.containsKey(char)) {
      result.write(vowelsReplace[char]);
    } else {
      result.write(char);
    }
  }

  return result.toString();
}

@pragma('vm:entry-point')
String _swapCase(String str) {
  final result = StringBuffer();
  for (int i = 0; i < str.length; i++) {
    final char = str[i];
    if (char == char.toUpperCase()) {
      result.write(char.toLowerCase());
    } else {
      result.write(char.toUpperCase());
    }
  }
  return result.toString();
}

