  print(checkDictCase({"a": "apple", "b": "banana"}));
  print(checkDictCase({"a": "apple", "A": "banana", "B": "banana"}));
  print(checkDictCase({"a": "apple", 8: "banana", "a": "apple"}));
  print(checkDictCase({"Name": "John", "Age": "36", "City": "Houston"}));
  print(checkDictCase({"STATE": "NC", "ZIP": "12345"}));
  print(checkDictCase({}));
}

