import 'dart:math';

@pragma('vm:entry-point')
int sumSquares(List<int> lst) {
  List<int> result = [];
  for (int i = 0; i < lst.length; i++) {
    if (i % 3 == 0) {
      result.add(lst[i] * lst[i]);
    } else if (i % 4 == 0 && i % 3 != 0) {
      result.add(lst[i] * lst[i] * lst[i]);
    } else {
      result.add(lst[i]);
    }
  }
  return result.fold(0, (sum, element) => sum + element);
}

