String strongestExtension(String className, List<String> extensions) {
  String strong = extensions[0];
  int myVal = extensions[0].split('').where((x) => x.toUpperCase() == x && x.toLowerCase() != x).length -
      extensions[0].split('').where((x) => x.toLowerCase() == x && x.toUpperCase() != x).length;

  for (String s in extensions) {
    int val = s.split('').where((x) => x.toUpperCase() == x && x.toLowerCase() != x).length -
        s.split('').where((x) => x.toLowerCase() == x && x.toUpperCase() != x).length;
    if (val > myVal) {
      strong = s;
      myVal = val;
    }
  }

  String ans = className + "." + strong;
  return ans;
}

