@pragma('vm:entry-point')
List<int> evenOddCount(int num) {
  int evenCount = 0;
  int oddCount = 0;
  for (var i in num.abs().toString().split('')) {
    if (int.parse(i) % 2 == 0) {
      evenCount += 1;
    } else {
      oddCount += 1;
    }
  }
  return [evenCount, oddCount];
}

@pragma('vm:entry-point')
void main() {
  // Test cases
  print(evenOddCount(-12)); // [1, 1]
  print(evenOddCount(123)); // [1, 2]
  print(evenOddCount(0)); // [1, 0]
  print(evenOddCount(246)); // [3, 0]
  print(evenOddCount(135)); // [0, 3]
}

tests:
void main() {
  final candidate = evenOddCount;

  expect(candidate(7), (0, 1));
  expect(candidate(-78), (1, 1));
  expect(candidate(3452), (2, 2));
  expect(candidate(346211), (3, 3));
  expect(candidate(-345821), (3, 3));
  expect(candidate(-2), (1, 0));
  expect(candidate(-45347), (2, 3));
  expect(candidate(0), (1, 0));
}

void expect(dynamic a, dynamic b) {
  if (a == b) return;

  if (a is List && b is List) {
    expectList(a, b);
  } else if (a is Map && b is Map) {
    expectMap(a, b);
  } else {
    throw '$a != $b';
  }
}

void expectList(List a, List b) {
  if (a.length != b.length) throw 'list lengths are not equal';

  for (var i = 0; i < a.length; i++) {
    expect(a[i], b[i]);
  }
}

void expectMap(Map a, Map b) {
  if (a.length != b.length) throw 'map lengths are not equal';

  for (var key in a.keys) {
    expect(a[key], b[key]);
  }
}

