@pragma('vm:entry-point')
List<int> eat(int number, int need, int remaining) {
  if (need <= remaining) {
    return [number + need, remaining - need];
  } else {
    return [number + remaining, 0];
  }
}

@pragma('vm:entry-point')
void main() {
  // Test cases
  print(eat(5, 6, 10)); // [11, 4]
  print(eat(4, 8, 9));  // [12, 1]
  print(eat(1, 10, 10)); // [11, 0]
  print(eat(2, 11, 5));  // [7, 0]
}

tests:
void main() {
  final candidate = eat;

  expect(candidate(5, 6, 10), [11, 4]);
  expect(candidate(4, 8, 9), [12, 1]);
  expect(candidate(1, 10, 10), [11, 0]);
  expect(candidate(2, 11, 5), [7, 0]);
  expect(candidate(4, 5, 7), [9, 2]);
  expect(candidate(4, 5, 1), [5, 0]);
}

